```solidity
struct ZoneParameters {
    bytes32 orderHash;
    address fulfiller;
    address offerer;
    SpentItem[] offer;
    ReceivedItem[] consideration;
    bytes extraData;
    bytes32[] orderHashes;
    uint256 startTime;
    uint256 endTime;
    bytes32 zoneHash;
}

function validateOrder(ZoneParameters calldata zoneParameters)
    external
    returns (bytes4 validOrderMagicValue);
```

